import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    names, raw = [], {}
    for i in range(n):
        name, _, val = data[1 + i].partition('=')
        names.append(name)
        raw[name] = val.split('$')
    memo = {}
    for start in names:
        stack = [start]
        while stack:
            v = stack[-1]
            if v in memo:
                stack.pop()
                continue
            parts = raw[v]
            missing = [p for p in parts[1::2] if p not in memo]
            if missing:
                stack.extend(missing)
                continue
            memo[v] = ''.join(memo[p] if k % 2 else p for k, p in enumerate(parts))
            stack.pop()
    print('\n'.join(f'{nm}={memo[nm]}' for nm in names))

